import java.util.*;

class Solution {
  public int validSubarrays(int[] nums) {
    // a subarray starting at i stays valid until the first smaller element
    Deque<Integer> stack = new ArrayDeque<>();
    int total = 0;
    for (int i = 0; i < nums.length; i++) {
      while (!stack.isEmpty() && nums[stack.peek()] > nums[i]) total += i - stack.pop();
      stack.push(i);
    }
    while (!stack.isEmpty()) total += nums.length - stack.pop();
    return total;
  }
}
